package vn.edu.eaut.library.dao;
import vn.edu.eaut.library.model.Review; import vn.edu.eaut.library.utils.DBConnection;
import java.sql.*; import java.util.*;
public class ReviewDAO {
 public List<Review> findByDocumentId(int documentId){List<Review> l=new ArrayList<>();String s="SELECT r.*,u.username,u.full_name AS user_full_name FROM document_reviews r JOIN users u ON r.user_id=u.user_id WHERE r.document_id=? ORDER BY r.created_at DESC";try(Connection c=DBConnection.getConnection();PreparedStatement p=c.prepareStatement(s)){p.setInt(1,documentId);try(ResultSet rs=p.executeQuery()){while(rs.next())l.add(map(rs));}}catch(SQLException e){throw new RuntimeException("Lỗi lấy đánh giá",e);}return l;}
 public Double average(int documentId){String s="SELECT AVG(rating) FROM document_reviews WHERE document_id=?";try(Connection c=DBConnection.getConnection();PreparedStatement p=c.prepareStatement(s)){p.setInt(1,documentId);try(ResultSet r=p.executeQuery()){if(r.next()){double v=r.getDouble(1);return r.wasNull()?0.0:v;}}}catch(SQLException e){throw new RuntimeException("Lỗi tính điểm đánh giá",e);}return 0.0;}
 public Review findByUser(int userId,int documentId){String s="SELECT r.*,u.username,u.full_name AS user_full_name FROM document_reviews r JOIN users u ON r.user_id=u.user_id WHERE r.user_id=? AND r.document_id=?";try(Connection c=DBConnection.getConnection();PreparedStatement p=c.prepareStatement(s)){p.setInt(1,userId);p.setInt(2,documentId);try(ResultSet r=p.executeQuery()){return r.next()?map(r):null;}}catch(SQLException e){throw new RuntimeException("Lỗi tìm đánh giá",e);}}
 public boolean upsert(Review x){String s="INSERT INTO document_reviews(user_id,document_id,rating,comment) VALUES(?,?,?,?) ON DUPLICATE KEY UPDATE rating=VALUES(rating),comment=VALUES(comment),updated_at=NOW()";try(Connection c=DBConnection.getConnection();PreparedStatement p=c.prepareStatement(s)){p.setInt(1,x.getUserId());p.setInt(2,x.getDocumentId());p.setInt(3,x.getRating());p.setString(4,x.getComment());return p.executeUpdate()>0;}catch(SQLException e){throw new RuntimeException("Lỗi lưu đánh giá",e);}}
 public boolean delete(int id,int userId){String s="DELETE FROM document_reviews WHERE review_id=? AND user_id=?";try(Connection c=DBConnection.getConnection();PreparedStatement p=c.prepareStatement(s)){p.setInt(1,id);p.setInt(2,userId);return p.executeUpdate()>0;}catch(SQLException e){throw new RuntimeException("Lỗi xóa đánh giá",e);}}
 private Review map(ResultSet r)throws SQLException{Review x=new Review();x.setReviewId(r.getInt("review_id"));x.setUserId(r.getInt("user_id"));x.setDocumentId(r.getInt("document_id"));x.setRating(r.getInt("rating"));x.setUsername(r.getString("username"));x.setUserFullName(r.getString("user_full_name"));x.setComment(r.getString("comment"));Timestamp t=r.getTimestamp("created_at");if(t!=null)x.setCreatedAt(t.toLocalDateTime());t=r.getTimestamp("updated_at");if(t!=null)x.setUpdatedAt(t.toLocalDateTime());return x;}
}
